mapper.select:
SELECT b.*, u.real_name AS customer_name, u.phone AS customer_phone
FROM booking b
LEFT JOIN sys_user u ON b.user_id = u.id


        AND b.booking_no LIKE CONCAT('%', #{bookingNo}, '%')


        AND b.user_id = #{userId}


        AND b.venue_id = #{venueId}


        AND b.status = #{status}


        AND b.payment_status = #{paymentStatus}


        AND b.booking_date >= #{bookingDateStart}


        AND b.booking_date <= #{bookingDateEnd}


ORDER BY b.created_at DESC

mapper.update:
UPDATE booking
status = #{status}, checkin_time = #{checkinTime}, checkout_time = #{checkoutTime}, attendee_count = #{attendeeCount}, fee_amount = #{feeAmount}, payment_status = #{paymentStatus}, payment_method = #{paymentMethod},
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM booking
WHERE venue_id = #{venueId}
  AND booking_date = #{bookingDate}
  AND status IN ('PENDING', 'APPROVED')
  AND (#{startTime} < end_time AND #{endTime} > start_time)

      AND id != #{excludeId}
